def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    from itertools import combinations

    # Helper to determine if a pair is separated by a horizontal aisle at row r
    def separated_by_row(r, pair):
        (x1, y1, x2, y2) = pair
        return (x1 <= r < x2) or (x2 <= r < x1)

    # Helper to determine if a pair is separated by a vertical aisle at column c
    def separated_by_col(c, pair):
        (x1, y1, x2, y2) = pair
        return (y1 <= c < y2) or (y2 <= c < y1)

    # Precompute sets of pairs separated by each possible row and column
    row_positions = list(range(1, M))  # aisles between rows
    col_positions = list(range(1, N))  # aisles between columns

    row_separated = {r: set() for r in row_positions}
    for idx, pair in enumerate(chatting_pairs):
        for r in row_positions:
            if separated_by_row(r, pair):
                row_separated[r].add(idx)

    col_separated = {c: set() for c in col_positions}
    for idx, pair in enumerate(chatting_pairs):
        for c in col_positions:
            if separated_by_col(c, pair):
                col_separated[c].add(idx)

    # If no aisles to add, return empty strings
    if K == 0 and L == 0:
        return ("", "")

    best_rows = []
    best_cols = []
    best_count = -1

    # Generate all combinations of rows and columns
    row_combos = list(combinations(row_positions, K)) if K > 0 else [()]
    col_combos = list(combinations(col_positions, L)) if L > 0 else [()]

    for r_combo in row_combos:
        # Union of pairs separated by chosen rows
        rows_union = set()
        for r in r_combo:
            rows_union.update(row_separated[r])

        for c_combo in col_combos:
            # Union of pairs separated by chosen columns
            cols_union = set()
            for c in c_combo:
                cols_union.update(col_separated[c])

            total_separated = rows_union | cols_union
            count = len(total_separated)

            if count > best_count:
                best_count = count
                best_rows = list(r_combo)
                best_cols = list(c_combo)

    # Convert to required string format
    row_str = " ".join(str(r) for r in sorted(best_rows))
    col_str = " ".join(str(c) for c in sorted(best_cols))

    return (row_str, col_str)

