def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize names to upper case for comparison
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    days_set = {day.upper() for day in days_of_week}

    def is_day_statement(stmt: str) -> bool:
        """Return True if the statement contains any day of the week."""
        stmt_upper = stmt.upper()
        return any(day in stmt_upper for day in days_set)

    def evaluate(stmt: str, speaker: str) -> bool:
        """Evaluate the truth value of a statement given the scenario."""
        stmt_upper = stmt.upper()
        # Self statements
        if "I AM GUILTY" in stmt_upper:
            return speaker == scenario
        if "I AM NOT GUILTY" in stmt_upper:
            return speaker != scenario
        # Statements about others
        # Extract name before "IS GUILTY" or "IS NOT GUILTY"
        if " IS GUILTY" in stmt_upper:
            name = stmt_upper.split(" IS GUILTY")[0].strip()
            return name == scenario
        if " IS NOT GUILTY" in stmt_upper:
            name = stmt_upper.split(" IS NOT GUILTY")[0].strip()
            return name != scenario
        # If statement does not match known patterns, assume it's irrelevant
        return True

    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmts:
            if is_day_statement(stmt):
                continue  # ignore day-of-week statements
            truth = evaluate(stmt, speaker_upper)
            if speaker_upper in liar_set:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement
    return True

