    dp[0] = 1
    for limit in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for k in range(1, m + 1):
            prefix[k] = (prefix[k - 1] + dp[k]) % MOD
        new_dp = [0] * (m + 1)
        for k in range(m + 1):
            low = k - limit
            if low <= 0:
                new_dp[k] = prefix[k]
            else:
                new_dp[k] = (prefix[k] - prefix[low - 1]) % MOD
        dp = new_dp
    return dp[m] % MOD

